-- ===========================================================
--  PharmaCore - Pharmaceutical company dataset import
--  Source: DDA pharmaceutical company research workbook
--  Companies, drug recalls, DDA notices and the official
--  drug categorisation rules (Drugs Categorization Rules, 2043)
--  Generated script - safe to re-run (clears imported rows first)
-- ===========================================================

SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRANSACTION;

-- Clear previously imported dataset rows
DELETE FROM DrugRecalls;
DELETE FROM Drugs;
DELETE FROM DdaNotices;
DELETE FROM Companies;
DELETE FROM DrugCategories;

-- Reset identity counters so ids restart from 1
DBCC CHECKIDENT ('Companies', RESEED, 0);
DBCC CHECKIDENT ('Drugs', RESEED, 0);
DBCC CHECKIDENT ('DrugRecalls', RESEED, 0);
DBCC CHECKIDENT ('DdaNotices', RESEED, 0);
DBCC CHECKIDENT ('DrugCategories', RESEED, 0);

-- Companies (123 rows)





COMMIT TRANSACTION;
GO

-- Summary
--   companies          : 123
--   duplicate rows     : 6 (de-duplicated: 124, 125, 126, 127, 128, 129)
--   drug recalls       : 16
--   catalogue drugs    : 15
--   dda notices        : 16
--   categorisation rows: 5
