INSERT INTO DrugCategories (Category, SubCategory, Definition, PrescriptionRequired, WhoMaySell, LabelWarning, LegalReference, SortOrder) VALUES (N'a', N'Sub-category 1', N'Narcotic drugs and any preparation containing related (narcotic) substances.', N'Yes - only on the prescription of a registered doctor.', N'Sold by a pharmacist or professional, or only in the presence of a pharmacist or professional.', N'"Caution Poison" and "May not be sold without the prescription of a registered medical practitioner".', N'Drugs Categorization Rules, 2043, Rule 10(2) and Schedule-4, Category a(1)', 1);
INSERT INTO DrugCategories (Category, SubCategory, Definition, PrescriptionRequired, WhoMaySell, LabelWarning, LegalReference, SortOrder) VALUES (N'a', N'Sub-category 2', N'Poisonous drugs (active ingredients listed in Schedule-4, sub-category 2).', N'Yes - only on the prescription of a registered doctor.', N'Sold by a pharmacist or professional, or only in the presence of a pharmacist or professional.', N'"Caution Poison" and "May not be sold without the prescription of a registered medical practitioner".', N'Drugs Categorization Rules, 2043, Rule 10(2) and Schedule-4, Category a(2)', 2);
INSERT INTO DrugCategories (Category, SubCategory, Definition, PrescriptionRequired, WhoMaySell, LabelWarning, LegalReference, SortOrder) VALUES (N'b', N'Not separately sub-divided in Schedule-4', N'Antibiotics, hormones and similar potent prescription medicines.', N'Yes - only on the prescription of a registered doctor.', N'Sold by a pharmacist or professional, or only in the presence of a pharmacist or professional.', N'"Caution" and "May not be sold without the prescription of a registered medical practitioner".', N'Drugs Categorization Rules, 2043, Rule 10(2) and Schedule-4, Category b', 3);
INSERT INTO DrugCategories (Category, SubCategory, Definition, PrescriptionRequired, WhoMaySell, LabelWarning, LegalReference, SortOrder) VALUES (N'c', N'Sub-category 1', N'Simple drugs listed in Schedule-4, sub-category 1 (for example Cyanocobalamine, Nicotinamide, Metronidazole, Aminophylline, Papaverine, Diloxanide, Clidinium bromide, Pholcodine).', N'No - may be sold even without a doctor''s prescription.', N'May be sold by any seller on the basis of experience; the presence of a pharmacist or professional is not compulsory.', N'Standard labelling only (no prescription warning).', N'Drugs Categorization Rules, 2043, Rule 10(2) and Schedule-4, Category c(1)', 4);
INSERT INTO DrugCategories (Category, SubCategory, Definition, PrescriptionRequired, WhoMaySell, LabelWarning, LegalReference, SortOrder) VALUES (N'c', N'Sub-category 2', N'Other similar simple / non-potent drugs (general over-the-counter type preparations).', N'No - may be sold even without a doctor''s prescription.', N'May be sold by any seller on the basis of experience; the presence of a pharmacist or professional is not compulsory.', N'Standard labelling only (no prescription warning).', N'Drugs Categorization Rules, 2043, Rule 10(2) and Schedule-4, Category c(2)', 5);
